  rn = `Не опубліковано`,
  an = `Приховано`,
  on = `Загальнодоступно`,
  sn = `Користувачі Steam бачать цю подію. Видимість події не можна скасувати, ви тільки можете видалити подію, якщо хочете її приховати.`,
  cn = `Непублічна та видима`,
  ln = `Цю подію побачать лише користувачі Steam, які мають пряме посилання. Її видимість не можна змінити: якщо подію треба приховати, її слід видалити.`,
  un = `Видимість у бібліотеці очікує модерування`,
  dn = `Приховано до %1$s`,
  fn = `Змінено. Приховано до початку події %1$s`,
  pn = `Ця подія опублікована, але прихована до певного часу. Інших дій не потрібно. Подія автоматично стане видимою для ваших користувачів Steam у визначений час.`,
  mn = `Ця подія автоматично стане видимою, коли вона розпочнеться.`,
