  gn = `Ці події заплановані на майбутнє, але вони будуть невидимі до часу свого початку. Інші дії не потрібні. `,
  _n = `Приховано, не опубліковано`,
  vn = `Ця подія — чернетка. Ніхто, крім учасників команди спільноти, не може її бачити. Усі зміни лишатимуться прихованими, доки ви не опублікуєте цю подію.`,
