  Sn = `Мова`,
  Cn = `Виберіть мову зі списку, щоби мати змогу відредагувати текстові поля саме для неї. Або скористайтеся можливістю експорту/імпорту кількох мов водночас.`,
  wn = `Мову не вибрано`,
  Tn = `Щоб опублікувати сторінку розпродажу, необхідно налаштувати її особливе посилання. Його використовують для створення посилання на розпродаж, яке доступне користувачам.`,
  En = `Щоб опублікувати цю сторінку, необхідно налаштувати особливе посилання на головну сторінку оновлення. Його використовують для створення посилання, яке доступне користувачам.`,
