  qn = `Заголовок розділу`,
  Jn = `Виберіть або варіант зі списку попередньо перекладених назв для показу вгорі цього розділу, або варіант «Введіть власну назву». Введіть текст у полі для пошуку попередньо перекладених назв.`,
  Yn = `Підзаголовок`,
  Xn = `(Максимум %1$s символів. З’являється вгорі сторінки події чи оголошення)`,
  Zn = `(Досягнуто макс. кількості символів: %1$s. З’являється вгорі сторінки події чи оголошення)`,
  Qn = `Сторінка творця другої версії надає зручний спосіб персоналізувати сторінки розробника, видавця або франшизи.`,
  $n = `Ця сторінка не видима. Опублікуйте сторінку, і тоді зможете зробити її своєю поточною сторінкою творця.`,
  er = `Ця сторінка <1>не є</1> вашою поточною сторінкою творця. Змінити це можна <2>тут</2>.`,
  tr = `Ця сторінка вже є вашою поточною сторінкою творця. Змінити це можна на <1>панелі сторінки творця</1>.`,
  nr = `Аватар`,
  rr = `Редагувати: <1>редактор сторінки творця</1>`,
  ir = `Підзаголовок`,
  ar = `Редагувати: <1>панель сторінки творця</1>`,
  or = `Вітаємо!`,
  sr = `<1>Ваші ігри</1> — ваші ігри показуються в списку пов’язаних застосунків нижче, і їх уже можна використовувати. Просто додайте й налаштуйте розділи нижче та організуйте ігри, завантажуваний вміст, демоверсії та саундтреки так, щоб це відповідало вашим потребам.`,
  cr = `<1>Пов’язування нових ігор</1> — якщо в списку відсутні якісь ігри, це означає, що ви не пов’язали їх із цією сторінкою творця. Щоб дізнатися, як це зробити, перегляньте <2>цю документацію</2>.`,
  lr = `<1>Стандартне налаштування</1> — нижче ви знайдете низку стандартних, уже сконфігурованих розділів, де виділені ваші популярні, рекомендовані та нещодавні релізи. Ви вильні використовувати ці стандартні розділи на власний розсуд.`,
  ur = `Щоб дізнатися більше, перегляньте документацію`,
  dr = `Категорія: %1$s`,
  fr = `Помилка клонування події`,
