  hr = `Трапилася помилка під час підготовки до публікації: %1$s`,
  gr = `Цей розпродаж має великий список пов’язаних застосунків, тому їхні позначки видобуваються із даних крамниці. Цей процес може тривати певний час.`,
  _r = `Не вдалося видобути позначки застосунків цього розпродажу із даних крамниці, тому редактор не можна відкрити безпечно. Оновіть сторінку, щоб спробувати знову.`,
  vr = `Не вдалося завантажити із крамниці кілька (%1$s) застосунків зі списку пов’язаних застосунків. Імовірна причина: їх заблоковано або вони більше не продаються. Їхні позначки не були видобуті, тому ці застосунки можуть не з’явитися в розділах, відфільтрованих за позначками (можете це проігнорувати, якщо застосунки заблоковані тощо): %2$s.`,
  yr = `Дата початку події`,
  br = `Дата оголошення`,
  xr = `Зараз — коли подію опубліковано`,
  Sr = `Зараз — коли оголошення опубліковано`,
  Cr = `Пізніше — запланувати початок події на майбутнє`,
