  Er = `Запланована дата публікації`,
  Dr = `Ви можете зробити подію видимою до дати її початку, якщо хочете повідомити про неї користувачам і дозволити їм підписатися на сповіщення.`,
  Or = `Ви можете зробити оголошення видимим до дати його початку, якщо хочете повідомити про нього користувачам і дозволити їм підписатися на сповіщення.`,
  kr = `Дата завершення події`,
  Ar = `Події у цій категорії зазвичай мають дату завершення.`,
  jr = `Виберіть кінцеву дату, щоби Steam знав, коли показувати сповіщення про завершення події. Це допоможе йому пріоритезувати показ ваших інших, ближчих або поточних подій.`,
  Mr = `Завершити, коли спливе певний термін після дати початку.`,
  Nr = `Ми заокруглюємо час завершення до %1$s`,
  Pr = `Дата завершення`,
  Fr = `Час завершення в редакторі показується згідно з вашим місцевим часовим поясом. Користувачі Steam також побачать цей час у власному часовому поясі.`,
  Ir = `Завершити у вказаний час…`,
