  Rr = `Автоматичні нагадування`,
  zr = `Якщо встановити початок події на майбутнє ТА зробити її видимою своїм прихильникам раніше, це дозволить їм увімкнути нагадування про початок події. Залежно від уподобань, Steam автоматично надсилатиме користувачам push-сповіщення та/або електронного листа.`,
  Br = `Цей тест надішле його на ваш акаунт лише в тому випадку, якщо вашу адресу електронної пошти підтверджено та/або якщо ви інсталювали %1$s.`,
