  Vi = `Обрати зображення`,
  Hi = `Імпорт HTML`,
  Ui = `Імпорт із HTML`,
  Wi = `Імпорт HTML-коду автоматично конвертує HTML у теги форматування Steam.`,
  Gi = `Надрукуйте або вставте HTML-код нижче.`,
  Ki = `Зберегти переноси`,
  qi = `Перехід на новий рядок у HTML ніяк не впливає на зміст, але у BBCode він створює порожній рядок. Якщо ви скористалися теґами <p> чи <br>, то не ставте позначку до цієї опції. Під час роботи з блогами, які зазвичай автоматично додають теґ <br> під час переходу на новий рядок, ви, швидше за все, схочете поставити позначку до цієї опції.`,
  Ji = `Конвертувати у BBCode:`,
