  cs = `Чи доречний цей допис для гравців, які переглядають вашу майстерню в Steam?`,
  ls = `Опублікувати і на сторінці подробиць демоверсії в бібліотеці`,
  us = `Чи доречний цей допис для користувачів, які грають у вашу демоверсію?`,
  ds = `Показувати як відібрану подію на сторінці гри в бібліотеці`,
  fs = `Перш ніж увімкнути розділ «У центрі уваги», надайте ілюстрацію для вкладки «%1$s» принаймні для англійської мови`,
  ps = `Показати автоматичний текст?`,
  ms = `Заголовок та підзаголовок події із затемнювальним оверлеєм буде автоматично накладено на правий верхній кут зображення.`,
  hs = `Ця подія тимчасово розміщуватиметься над розділом діяльності кожного користувача. Слід використовувати лише для великих подій із належними перервами між ними, щоб їх не завжди було видно на сторінці гри в бібліотеці.`,
  gs = `Показувати в розділі бібліотеки «Що нового»`,
  _s = `Показ вашого допису для гравців у розділі бібліотеки «Що нового» залежатиме від проведеного часу в грі та інших факторів.`,
  vs = `Показувати на сторінці гри в бібліотеці`,
  ys = `Показувати на сторінці в крамниці`,
  bs = `Обдумано вибирайте, який саме вміст буде показуватися користувачам Steam, котрі мають вашу гру в бібліотеці, і тим, хто відвідує сторінку вашого продукту в крамниці. Наприклад, не варто додавати посилання на придбання вашої гри в іншій крамниці. Вам також слід дотримуватися %1$s.`,
  xs = `загальних вимог до вмісту у Steam`,
  Ss = `Приховати на домашній сторінці бібліотеки`,
  Cs = `Включає вміст лише для дорослих`,
  ws = `Використовуйте, якщо допис включає відверті зображення чи інший вміст. Доступно тільки для застосунків, позначених як «лише для дорослих».`,
  Ts = `Приховати на сторінці гри в бібліотеці`,
  Es = `Приховати на сторінці в крамниці`,
  Ds = `Налаштування модерування. Перезаписують будь-які партнерські налаштування.`,
  Os = `Змінити регіональне обмеження`,
  ks = `Лише розділені комами дволітерні коди країн.`,
  As = `Поточний тип події «%1$s» не показується на цьому типі сторінок.`,
  js = `Показувати в Steam China`,
