  Js = `Колір стрілки каруселі`,
  Ys = `Якщо тло або зображення тла дуже світлі, стрілку можна не помітити. Виберіть це налаштування, щоб змінити стандартний білий колір стрілок каруселі.`,
  Xs = `Якщо тло або зображення тла дуже світлі, стрілку можна не помітити. Виберіть це налаштування, щоб змінити стандартний біло-сірий колір навігаційної стежки в каруселі. Стосується головним чином менших екранів, як-от Steam Deck.`,
  Zs = `Завантаження інформації про демоверсію`,
  Qs = `Немає випущеної демоверсії, з якою можна було б пов’язати цей допис.`,
  $s = `Щоб пов’язати цю подію з демоверсією, потрібно спершу зберегти її.`,
  ec = `Опублікована подія або оголошення з’явиться на сторінці демоверсії в бібліотеці. Це дає змогу взаємодіяти з шанувальниками, які мають лише вашу демоверсію. `,
  tc = `Тематичні події: %1$s`,
  nc = `Геловін 2022`,
  rc = `Ця подія пов’язана з оновленням вашої гри до Геловіну 2022? Якщо ви додаєте до цієї гри нові мапи, текстури, ілюстрації чи інший вміст із нагоди Геловіну або ж проводите тимчасові події з особливим геловінським вмістом, випробуваннями чи подібними заходами, ми хотіли б знати про це. Ми шукаємо способи показати тематичні події ширшій аудиторії, але спочатку нам потрібно зрозуміти, як саме розробники збираються відзначити свято у своїх іграх (і чи збираються взагалі). Будь ласка, клацніть «Вкл.» нижче, якщо ця подія є оновленням до Геловіну 2022.`,
  ic = `Тематичні геловінські події`,
  ac = `Плануєте провести подію чи додати тематичний геловінський вміст? Див. %1$s, щоб дізнатися більше про участь у цьогорічному геловінському розпродажі зі своєю особливою внутрішньоігровою подією.`,
  oc = `документацію стосовно геловінського розпродажу`,
  sc = `Новий завантажуваний вміст чи доповнення до гри`,
  cc = `Постійне геловінське доповнення до гри`,
  lc = `Оголошуйте у своїй грі обмежені в часі події на геловінську тематику, які дають гравцям додаткові предмети, бонуси, привілеї, нагороди, досвід тощо. Вони мають час початку й час завершення.`,
  uc = `Категорія номінацій нагород Steam`,
  dc = `Виберіть конкретну категорію, у якій шанувальники будуть номінувати вашу гру. Вони зможуть зробити це безпосередньо під час події!`,
  fc = `Більшість категорій нагород Steam цього року присвячені іграм, що були випущені в %1$s (після проведення останніх номінацій на нагороди Steam %2$s). Оскільки ваша гра вийшла до цієї дати, вона може кваліфікуватися лише на одну категорію — «Сродна праця».`,
  pc = `Щоб дізнатися більше інформації й завантажити набір ресурсів для нагород Steam із шаблонами зображень, які можна використати для маркетингових матеріалів, перегляньте нашу документацію <1>тут</1>.`,
  mc = `Цю гру не можна номінувати в жодній категорії. Якщо ви вважаєте, що це помилка, зверніться до <1>служби підтримки Steamworks</1>.`,
  hc = `Підтвердження невидимості сторінки крамниці`,
  gc = `Сторінка застосунку %1$s в крамниці наразі невидима. Публікація цієї події сповістить користувачів про існування гри. Якщо ви все ж вирішите опублікувати цю подію, то повинні чітко вказати це тут.`,
  _c = `Опублікувати подію всупереч невидимості сторінки крамниці?`,
