  DS = `Зміна метаданих застосунку`,
  OS = `Надає дозвіл вивантажувати сховища, тестувати функції Steamworks, налаштовувати комплекти, досягнення і таблиці лідерів, публікувати колекційні картки тощо. Також надає доступ адміністратора спільноти Steam до будь-якого застосунку в групі.`,
  kS = `Публікація змін застосунку в Steam`,
  AS = `Дозволяє публікувати зміни для вашого продукту, зроблені на сайті розробників Steamworks у розділі «Технічні інструменти» → «Змінити налаштування Steamworks».`,
