  KS = `Редагування даних локалізації в крамниці`,
  qS = `Дозволяє редагувати будь-які дані на вкладках налаштування сторінки в крамниці, які мають одне чи кілька полів для локалізації, як-от опис і зображення. Не дає дозволу на публікацію та доступу до маркетингових інструментів, як-от раундів видимості. Є частиною функціоналу дозволу «Зміна маркетингових даних застосунку».`,
