  hC = `Ці користувачі отримуватимуть електронні листи про майбутні пропозиції, цільові події та оголошення нових функцій у Steam.`,
  gC = `Цьому користувачеві було надіслано запрошення отримати «Дозвіл щодо сповіщень Steamworks», але він ще не прийняв його.`,
