  IC = `Це кількість пікселів, на яку слід змістити вміст сторінки розпродажу вниз, щоб зробити місце для заголовка та дат на зображенні тла. Потреби змінювати це значення більше не буде, окрім як для досягнення якогось незвичайного ефекту.`,
  LC = `Стандартне (і максимальне) значення повинно бути %1$s`,
