  rw = `Типово Steam автоматично підтягуватиме будь-яку трансляцію наживо, пов’язану з будь-якою грою із цієї сторінки розпродажу. Якщо це підходить для цього розпродажу, не потрібно ніяких додаткових дій. Але якщо ви бажаєте власноруч визначати, яка саме трансляція має з’являтися на сторінці, увімкніть цю опцію та виберіть потрібні трансляції на відповідній вкладці.`,
  iw = `Загальна конфігурація сторінки`,
