  lw = `У цьому вікні можна створити один або кілька стилів тла власного розділу. Ці стилі можна вибрати для будь-якого розділу на цій сторінці. Зміна стилю миттєво застосовується до всіх розділів, які його використовують. Це дозволяє одночасно керувати виглядом кількох розділів і підтримувати їхню узгодженість.`,
