  Vw = `Дозволяє додавати або імпортувати список продуктів для виділення на сторінці розпродажу, застосувати мітки до кожного з них, а потім за допомогою фільтрів міток наповнювати розділи вмістом. Загалом це призначено для великих розпродажів із сотнями продуктів і є заскладним для невеликих розпродажів.`,
