  aT = `Відповідні продукти: %1$s`,
  oT = `Це список усіх пов’язаних продуктів цього розпродажу, що наразі збігаються з фільтром нижче.`,
  sT = `Відфільтровані продукти: %1$s`,
  cT = `Це список усіх продуктів, які не відповідають фільтрам і не будуть показані. Корисно для визначення причин відсутності певного продукту в розділі.`,
  lT = `Невикористані продукти: %1$s`,
  uT = `Це список усіх пов’язаних продуктів цього розпродажу, які не входять до ЖОДНОГО з розділів (не додані ані вручну, ані за допомогою фільтру). Його можна використовувати для групування невикористаних продуктів та щоби переконатися, що всі предмети показані під час розпродажу.`,
  dT = `Показати розбивку міток`,
  fT = `Сховати розбивку міток`,
  pT = `Пов’язані продукти утворюють перелік разом із пов’язаними атрибутами. Їх можна додати до розпродажу за допомогою фільтрів, які дозволяють обрати продукти на основі визначених критеріїв. Важливо зазначити, що ці продукти насправді не є частиною розпродажу й не видимі для користувачів, допоки їх не буде включено у вкладку чи розділ розпродажу за допомогою фільтру.`,
  mT = `Надає список усіх міток відповідних продуктів і їхню кількість. Корисно для визначення доступності інших розбивок міток. Кожну мітку можна обрати для перегляду продуктів у списку відповідної мітки.`,
  hT = `Фільтр не встановлено — включено всі пов’язані продукти`,
  gT = `Цей розділ налаштовано для показу продуктів за фільтрами, що будуть застосовані до всіх пов’язаних продуктів розпродажу. Але наразі цей фільтр не налаштовано. Клацніть кнопку нижче, щоби зробити це.`,
  _T = `Змінити фільтр`,
  vT = `Це дозволить налаштувати фільтр, пов’язаний із цим розділом, і показувати тут лише вибрані продукти з розпродажу.`,
  yT = `Оглянути пов’язані продукти`,
  bT = `Фільтр розділу`,
