  ET = `Головна сторінка оновлення`,
  DT = `Сторінка творця`,
  OT = `Потрібно принаймні один раз зберегти цю подію, перш ніж вмикати функцію розпродажу.`,
  kT = `Збережіть цю сторінку, щоб продовжити.`,
  AT = `Розпродаж`,
  jT = `Шрифт сторінки розпродажу`,
  MT = `Шрифт для назви й текстових розділів на цій сторінці розпродажу`,
