  RT = `Посилання, яке зазвичай вставляється в BB-код і використовується для показу логотипу на панелях підписки`,
  zT = `Особливе посилання на розпродаж`,
  BT = `Буде вказано в кінці посилання на сторінку розпродажу, на яку користувачі заходитимуть з вашої домашньої сторінки творця. Не має містити пробілів, оскільки після кодування таку адресу важче читати. Замість пробілів використовуйте «_» (нижню риску). У цьому полі можна вказувати лише символи, цифри, «_» та «-». Наприклад: Halloween2019, Valentines, Best_Sale_Ever.`,
  VT = `Особливе посилання на головну сторінку оновлення`,
  HT = `Буде вказано в кінці посилання на сторінку в крамниці та спрямовуватиме користувачів на цю головну сторінку оновлення. Не має містити пробілів, оскільки після кодування таку адресу важче читати. Замість пробілів використовуйте «_» (нижню риску). У цьому полі можна вказувати лише символи, цифри, «_» та «-». Наприклад: Halloween2019, Valentines, Best_Sale_Ever.`,
  UT = `Посилання на подію, що почалася`,
  WT = `Показується в крамниці Steam після початку події`,
  GT = `Не використовуйте великі літери в назвах розділів`,
  KT = `Стандартно для усіх назв розділів використовують букви верхнього регістру. Поставивши тут прапорець, ви дозволите використання великих та малих літер для назв розділів відповідних мов`,
  qT = `AppID рекламованого застосунку`,
  JT = `Якщо вказати AppID рекламованого застосунку для цієї сторінки, ми відстежуватимемо всі переходи з неї на сторінку застосунку в крамниці`,
  YT = `(Лише для Valve) Вказати steampowered.com/sale як адресу сторінки`,
  XT = `Це дозволяє використовувати особливе посилання (див. вище) для сторінки розпродажу верхнього рівня «sale/» у крамниці Steam. Це означає, що ми також підтримуємо, просуваємо та показуємо сторінку розпродажів, а не лише сторінку творця.`,
  ZT = `Розмір шрифту назви розділу`,
  QT = `Розмір шрифту в пікселях для назви розділу`,
  $T = `Змінити колір всього тла`,
  eE = `Скинути`,
  tE = `Фонове відео`,
  nE = `Фонове відео (формат WebM)`,
  rE = `Фонове відео (формат MP4)`,
  iE = `Застосування: установіть обидві URL-адреси для показу відео поверх зображення тла. Кожен формат є обов’язковим на різних платформах.`,
  aE = `Якого типу має бути цей розділ?`,
  oE = `Ці налаштування визначають видимість на головній сторінці. Усі дані з цього розділу буде надіслано, і вони стануть видимі особі, що перевірятиме пам’ять. Іншими словами, насправді ми не приховуємо дані.`,
  sE = `Завжди приховувати цей розділ`,
  cE = `Приховати цей розділ до певного часу?`,
  lE = `Приховати цей розділ після певного часу?`,
  uE = `(використовувати місцевий час)`,
  dE = `Приховувати розділ на Steam Deck та в режимі Big Picture`,
  fE = `Не приховано`,
  pE = `Приховувати на Steam Deck та в режимі Big Picture`,
  mE = `Показувати лише на Steam Deck та в режимі Big Picture`,
  hE = `Показувати розділ на основі режиму дослідження Фестивалю новинок`,
  gE = `Персоналізований порядок стає доступним після завершення довільного впорядкування та появи рекомендацій для користувача. Навіть після цього користувач може перемкнутися на довільний порядок. Коли ця функція не доступна, сторінка завжди показується в довільному порядку.`,
  _E = `Будь-який (показувати завжди)`,
  vE = `Показувати лише в персоналізованому режимі`,
  yE = `Показувати, лише якщо доступна персоналізована добірка, навіть якщо користувач вибрав довільну`,
