  xE = `Показати кнопку «Оглянути все»`,
  SE = `Стандартно надане посилання створить посилання для продукту. Окрім цього, до регіону продукту буде додано кнопку «Оглянути все».`,
  CE = `Вимкнути фільтрацію за ID вкладки`,
  wE = `Якщо ввімкнено, то звичайне фільтрування за ID на активній вкладці вимикається. Це корисно у випадках, якщо ви хочете, щоби кілька вкладок показували всі застосунки, як-от усе зі списку бажаного користувача.`,
