  IE = `Якір розділу (необов’язково)`,
  LE = `Якір, який за бажанням можна використовувати для прямих посилань і переходів до цього розділу на сторінці.`,
  RE = `Використовується для прямих посилань на розділ. Дозволені лише літери нижнього регістру (a–z), цифри (0–9), риски (-) та підкреслення (_).`,
  zE = `Цей тип розділу має фіксовану назву, яку не можна змінити.`,
  BE = `Показати на вкладках: `,
