  GE = `Функція вимкнена, доки не вибрано принаймні одну вкладку. Дозволяє перетворити список показаних на вкладці продуктів на список прихованих.`,
  KE = `[Усе]`,
  qE = `Редагувати`,
  JE = `Показати на вкладках`,
