  XE = `Вміст`,
  ZE = `Розкладка`,
  QE = `Тло`,
  $E = `Дозволяє налаштувати вигляд тла для цього розділу розпродажу.`,
  eD = `Вкладки`,
  tD = `Визначає, на яких вкладках має з’являтися цей розділ.`,
