  rD = `Видимість`,
  iD = `Визначає, чи видимий цей розділ для користувачів, які переглядають вашу сторінку, і якщо так, то коли.`,
  aD = `Продуктів: %1$s`,
  oD = ` — Показано як карусель`,
  sD = ` У вкладках: %1$s`,
  cD = `ID головної підписки (необов’язково)`,
