  uD = `Ігор на сторінці`,
  dD = `Якщо встановити як нуль, використовуватиметься стандартне значення (12 назв). В іншому разі система спробує завантажувати вказану кількість застосунків на сторінку й приховуватиме решту за кнопкою «Показати більше».`,
