  TD = `Показ одного чи кількох зображень як одного елемента, каруселі або сітки. За бажанням можна надати локалізовані зображення з посиланнями на інші сторінки в крамниці.`,
  ED = `Показ одного чи кількох зображень як одного елемента, каруселі або сітки. За бажанням можна надати локалізовані зображення.`,
  DD = `Зображення для назви чи заголовка`,
  OD = `Показ одного зображення, яке можна локалізувати, як заголовка чи назви.`,
  kD = `Перехресне просування сторінки розпродажу`,
  AD = `Цей віджет підтягує ігри з пов’язаної сторінки розпродажу, що активна в той самий час. Переконайтеся, що її вміст відповідає тематиці вашої події.`,
  jD = `Відтворювач трансляції`,
  MD = `Якщо трансляцію ввімкнуто на цій сторінці, стандартно відеопрогравачі мають з’явитися вгорі сторінки. Цей віджет дозволяє вказати місце на сторінці, де показуватиметься відтворювач трансляції.`,
  ND = `Опис події`,
