  BD = `Показує віджет із назвою, описом і кнопкою для відстеження відповідної групи спільноти Steam або домашньої сторінки розробника/видавця.`,
  VD = `Куратор: %1$s`,
  HD = `Карусель із трейлерами ігор`,
  UD = `Великий розділ для показу трейлерів: спочатку відтворюватиметься мікротрейлер, а після нього — основний трейлер зі сторінки в крамниці. Інформація про гру з’явиться праворуч.`,
  WD = `Застосунки будуть видимі в цьому розділі, лише якщо мають трейлери.`,
  GD = `Показувати один список творця`,
  KD = `Показує карусель зі списками творця, вибраними в розділі «Керувати списками» в налаштуваннях сторінки творця.`,
  qD = `Показувати всі списки творця`,
  JD = `Показує карусель зі всіма списками творця, вибраними в розділі «Керувати списками» в налаштуваннях сторінки творця.`,
  YD = `Списки та рекомендації від кураторів`,
  XD = `Дозволяє вказати місце на сторінці, де показуватимуться списки та рекомендації від кураторів. Стандартно користувачі, що відстежують кураторів Steam, мають побачити рекомендацію відстежуваного куратора щодо представлених на розпродажі ігор унизу сторінки. Ви можете вибрати місце показу цього розділу.`,
  ZD = `Показує рекомендації та списки кураторів: автоматично показує списки кураторів Steam, за якими стежить користувач, а також списки вибраних кураторів мовою користувача Steam, яких він відстежує.`,
  QD = `Необов’язково: показувати час початку`,
