  eO = `Показувати список рекомендацій від кураторів:`,
  tO = `За бажанням оберіть списки кураторів, які були створені для цього розпродажу. Куратори можуть створювати ці списки лише після початку розпродажу.`,
  nO = `Виберіть список для показу`,
  rO = `Куратори можуть створювати списки ігор, відібраних для цього розпродажу. У цьому діалоговому вікні за бажанням можна обрати один чи кілька списків для показу на сторінці. Списки відібраного побачать усі користувачі Steam, які відвідають цю сторінку.`,
  iO = `Неможливо вибрати куратора. Розпродаж має розпочатися і бути видимим.`,
