  sO = `Кнопки вкладки`,
  cO = `Необов’язковий розділ, корисний лише за наявності вкладки. Він показує вкладки як кнопки, і його найліпше розмістити в кінці сторінки для зручності користувачів, що могли пропустити вкладки на сторінці.`,
  lO = `Питання з варіантами відповідей`,
  uO = `У цьому розділі можна створити питання з декількома варіантами відповідей на кшталт вікторини для користувачів.`,
