  LP = `Застосуйте фільтри після завантаження подробиць про продукт, щоб перевірити, чи має він бути показаний у цьому розділі. Наприклад, якщо гра має стан «Незабаром» і ви не хочете, щоб вона входила до цього розділу, поки не буде випущена, використайте цей фільтр.`,
  RP = `Зі знижкою`,
  zP = `Показувати лише найдешевші варіанти купівлі вмісту. Інакше кажучи, система не покаже дорожче видання Deluxe зі знижкою.`,
  BP = `З демоверсією`,
  VP = `Показувати лише ігри з демоверсіями, у які користувачі зможуть одразу зіграти. Сюди не входять ігри без демоверсій та ігри з неактивними демоверсіями.`,
  HP = `З вільним доступом`,
  UP = `Показувати лише ігри у вільному доступі.`,
  WP = `З тестуванням`,
  GP = `Показувати лише тестування ігор, до яких користувачі можуть приєднатися або в застосунки яких можуть одразу почати грати.`,
  KP = `Стан випуску:`,
  qP = `Без фільтрування`,
  JP = `Незабаром`,
  YP = `Показувати лише застосунки, ігри та завантажуваний вміст, які ще не вийшли в Steam.`,
  XP = `Випущено`,
  ZP = `Показувати лише застосунки, ігри та завантажуваний вміст, які вже вийшли в Steam і які можна купити й зіграти в них (зокрема продукти в дочасному доступі).`,
  QP = `Показувати лише цю кількість застосунків`,
  $P = `Це найбільша кількість застосунків із пов’язаного джерела, які ми покажемо в цьому розділі.`,
  eF = `Сортувати`,
  tF = `Доречність (?)`,
  nF = `Оцінка доречності, вирахувана на основі того, коли гра вийшла та як добре продається.`,
  rF = `Назва`,
  iF = `Продажі`,
  aF = `Додавання до списків бажаного`,
  oF = `Оцінка`,
  sF = `Одночасні гравці`,
  cF = `Мінімальна кількість результатів для розділу`,
  lF = `Показувати цей розділ, лише якщо у користувача є не менше ніж ця кількість продуктів, які відповідають сторінці та позначці.`,
  uF = `Випадковий порядок`,
  dF = `Надсилає запит на більший набір результатів з каталогу, а потім повертає випадкову добірку його елементів. Поле сортування продовжує працювати, якщо кількість елементів, які проходять фільтр, перевищує ліміт результатів.`,
  fF = `Показати останні події й оголошення для відібраних ігор.`,
  pF = `Показати нещодавні події та оголошення усіх ігор: спочатку придбаних, у списку бажаного та тих, що відстежуються, а вже потім хітів продажів.`,
  mF = `Показати останні події та оголошення. <1>Переглянути та додати нові події</1>.`,
  hF = `Розділ %1$s`,
  gF = `Це внутрішня назва.%1$sЗагальнодоступна назва: %2$s.`,
  _F = `[%1$s]`,
  vF = `Не визначено жодного розділу розпродажу`,
  yF = `Натисніть нижче, щоб додати свій перший розділ розпродажу.`,
  bF = `Мітка`,
  xF = `Колір мітки`,
  SF = `Вимкнути відступ угорі розділу`,
