  OF = `Кольори серії подій`,
  kF = `Кольори серії прем’єр`,
  AF = `Кольори серії повторів`,
  jF = `Колір мітки`,
  MF = `Градієнт тла (ліворуч)`,
  NF = `Градієнт тла (праворуч)`,
  PF = `Сфокусований градієнт тла (ліворуч)`,
