  WF = `Колір активної навігаційної стежки`,
  GF = `Колір навігаційної стежки`,
  KF = `Стилі навігаційних стежок у каруселі`,
  qF = `Капсульний стиль`,
  JF = `Круглий стиль`,
  YF = `Квадратний стиль`,
