  Pz = `Для кожного рядка можна окремо вибрати кількість стовпців (від 1 до 5).`,
  Fz = `Ця дія призведе до вилучення стовпця медіа з введеними даними. Її не можна потім скасувати. Ви впевнені?`,
  Iz = `Послідовність показу`,
