  Hz = `Додає до 4 блоків на рядок.`,
  Uz = `Вилучає цей блок. З вилученням останнього блока рядок буде видалено.`,
  Wz = `Перетягує блок на місце іншого, щоб замінити його вміст.`,
  Gz = `Змінити розмір елемента сітки. У рядках, які містять 2 або 3 елементи сітки, можна збільшити розмір одного елемента й відповідно зменшити розмір інших елементів. Клацніть тут, щоб збільшити розмір цього елемента.`,
  Kz = `Змінити розмір елемента сітки. У рядках, які містять 2 або 3 елементи сітки, можна збільшити розмір одного елемента й відповідно зменшити розмір інших елементів. Клацніть тут, щоб зменшити розмір цього елемента.`,
  qz = `Якщо є три чи більше стовпці, горизонтальне подання не підтримується, оскільки немає достатньо місця для одночасного показу медіа та тексту.`,
  Jz = `Горизонтальне подання з текстом ліворуч і медіа праворуч.`,
