  fB = `Показувати знімок екрана та мікротрейлер під час наведення вказівника`,
  pB = `Кнопка відтворення трейлера`,
  mB = `Колір кнопки відтворення`,
  hB = `Колір кнопки відтворення, що буде поверх кожного трейлера в цьому розділі. Не змінюйте його, щоби використовувати стандартний.`,
  gB = `Колір кнопки відтворення під час наведення`,
  _B = `Колір кнопки відтворення, коли користувач наводить на трейлер вказівник. Застосовується до всіх трейлерів у цьому розділі. Не змінюйте його, щоби використовувати стандартний.`,
  vB = `Стандартний показ трейлера`,
  yB = `Встановлює вигляд медіафалу перед клацанням по ньому: як знімок екрана трейлера, як повторення мікротрейлера або як знімок екрана із повторюваним мікротрейлером під час наведення на нього вказівника миші. У всіх випадках клацання призведе до відкриття трейлера в новому діалоговому вікні.`,
  bB = `Співвідношення сторін`,
  xB = `16:9`,
  SB = `Співвідношення сторін ілюстрації, необхідне для виділення місця на сторінці для неї під час завантаження. Записується під час завантаження ілюстрації; введіть значення вручну для завантажених раніше ілюстрацій.`,
