  hV = `Дозволяє налаштувати розмір простору, що використовуватиметься для тексту, в діапазоні від %1$s до %2$s. Стандартне значення — %3$s.`,
  gV = `Скинути масштабування`,
  _V = `Перетягніть сюди зображення (PNG/JPG/GIF/WEBP) чи відео (MP4). Максимальний розмір — 20 МБ.`,
  vV = `Перетягніть сюди статичні зображення (PNG/JPG). Максимальний розмір — 20 МБ.`,
  yV = `Вимикає версію для мобільного та скидає її налаштування`,
  bV = `Версія для мобільного — це необов’язкове налаштування, що дозволяє повністю персоналізувати цю сітку медіавмісту для перегляду на мобільних пристроях. Підтримує надання іншого тексту, зображень й елементів керування для екранів мобільних пристроїв.`,
  xV = `Ви дійсно бажаєте вимкнути версію для мобільного? Відповідні дані буде вилучено. Цю дію неможливо скасувати.`,
  SV = `Вимикає версію для планшета та скидає її налаштування`,
