  XK = `Виберіть тип вмісту, який потрібно імпортувати. Введіть кожен ідентифікатор в окремому рядку`,
  ZK = `Увага: банер не з’явиться у крамниці Steam, тому що опцію «Показувати на сторінці продукту в крамниці» вимкнуто на вкладці «Параметри».`,
  QK = `Ви дійсно бажаєте вилучити цей розділ із цієї сторінки розпродажу?`,
  $K = `Опис події вже відображатиметься в іншому розділі. Ви дійсно бажаєте показувати його тут також?`,
  eq = `Рекомендації від кураторів уже буде показано в іншому розділі. Ви дійсно бажаєте, щоб вони з’явилися і тут?`,
  tq = `Попередній розділ також налаштовано на показ трансляції наживо. Цей розділ буде проігноровано.`,
  nq = `Завжди видно`,
  rq = `Видно лише в день %1$s`,
  iq = `Видно лише в день %1$s з %2$s до %3$s`,
  aq = `Видно, починаючи з дня %1$s о %2$s`,
  oq = `Фільтр:`,
  sq = `Показати все`,
  cq = `Продукти лише за день %1$s (%2$s)`,
  lq = `Видимість нових продуктів`,
  uq = `Визначає, в який день розпродажу визначені продукти будуть показані як вибрані. Типово вони показуватимуться протягом усього розпродажу, але ви можете вказати конкретні дні для конкретних продуктів.`,
  dq = `Тло профілю за днями`,
  fq = `Стандартно одне зображення використовуватиметься як верхнє зображення тла протягом всього розпродажу. Вище значення цього параметра уможливить показ різних ілюстрацій кожного дня. Ілюстрація останнього дня залишиться на сторінці й після завершення події. Кількість доступних зображень тла залежить від кількості днів розпродажу, вказаної на вкладці параметрів.`,
  pq = `Верхні зображення розпродажу %1$s`,
  mq = `Одне верхнє зображення для всього розпродажу`,
  hq = `Усі попередньо вибрані верхні зображення будуть вилучені. Продовжити?`,
  gq = `Ілюстрації якого дня ви бажаєте переглянути чи оновити?`,
  _q = `Попередній перегляд показує ілюстрації, вивантажені для обраного дня. Усі ілюстрації, що пов’язані з верхнім зображенням, також будуть застосовані до поточного обраного дня.`,
  vq = `Видно лише в день %1$s з %2$s до %3$s`,
  yq = `Видно, починаючи з дня %1$s о %2$s`,
  bq = `або`,
  xq = `Додані продукти`,
  Sq = `Дозволяє визначити, які продукти будуть показані як вибрані в цьому розділі, а також в які дні (за потреби).`,
