  Oq = `Не знайдено`,
  kq = `Не вдалося знайти інформацію для (%1$s %2$s). Імовірно, ви неправильно ввели назву, або цей продукт може бути недоступним у вашому регіоні чи його приховано.`,
  Aq = `Не дозволено`,
  jq = `Цей продукт не можна додати, оскільки він не пов’язаний із домашньою сторінкою творця (розробника, видавця чи франшизи) цієї сторінки розпродажу. Пов’яжіть продукт і перезавантажте сторінку розпродажу, щоб оновити зв’язок.`,
  Mq = `Комплект не дозволений`,
  Nq = `Цей комплект не можна додати, оскільки він не пов’язаний із домашньою сторінкою творця (розробника, видавця чи франшизи) цієї сторінки розпродажу. Пов’яжіть комплект і перезавантажте сторінку розпродажу, щоб оновити зв’язок. Ось застосунки, не пов’язані з цим творцем: (%1$s).`,
  Pq = `Пакунок не дозволений`,
  Fq = `Цей пакунок не можна додати, оскільки він не пов’язаний із домашньою сторінкою творця (розробника, видавця чи франшизи) цієї сторінки розпродажу. Пов’яжіть пакунок і перезавантажте сторінку розпродажу, щоб оновити зв’язок. Ось застосунки, не пов’язані з цим творцем: (%1$s).`,
  Iq = `Ця подія клонована з попередньої. Valve повинна ввімкнути функції сторінки розпродажу, перш ніж ви зможете редагувати її.`,
