  Hq = `Сторінку розпродажу пов’язано.`,
  Uq = `Подія існує, але створити посилання наразі неможливо. Не налаштовано технічний бік розпродажу або не додано ігри, тому відсутній потрібний для пов’язання внутрішній ідентифікатор. Попросіть організаторів налаштувати сторінку розпродажу та спробуйте пов’язання знову.`,
  Wq = `Завантаження інформації про сторінку розпродажу`,
  Gq = `Сторінка розпродажу ще не опублікована та не видима.`,
  Kq = `Назва сторінки розпродажу: %1$s`,
  qq = `На цій сторінці розпродажу немає капсульних зображень події`,
  Jq = `Вибір застосунків`,
  Yq = `Пріоритезація за списками бажаного`,
  Xq = `Якщо на перехресно просунутій сторінці розпродажу більшість ігор майбутні, ймовірно, вони не матимуть даних про дохід, і в цьому разі краще пріоритезувати за їх додаваннями до списку бажаного.`,
  Zq = `Пріоритезація за доходом`,
  Qq = `Це стандартна опція. Перевага віддаватиметься видимим користувачам іграм із перехресно просунутої сторінки на основі інформації про продажі.`,
  $q = `Якщо сторінок розпродажу більше ніж одна, розділ стає каруселлю з одним слайдом на кожну сторінку розпродажу в поточному порядку. Перетягніть, щоб змінити порядок.`,
  eJ = `Додати ще одну сторінку розпродажу`,
  tJ = `Редактор обмеженої наявності`,
  nJ = `Додати опцію обмеженої наявності`,
  rJ = `Редагувати опис`,
  iJ = `Редагувати опис після розділу`,
  aJ = `Введіть опис`,
  oJ = `Редагувати короткий опис, що з’явиться поруч із продуктами.`,
  sJ = `Набір обладнання`,
  cJ = `Набір обладнання, який купує користувач у цьому блоці.`,
  lJ = `Залиште опис порожнім — тоді ця опція буде показана одним рядком: назва й ціна пакунка та кнопка «Придбати» без зображення чи очікуваного терміну доставки.`,
  uJ = `Подання`,
  dJ = `Сіткою: блоки фіксованої ширини показані рядками. Списком: у рядку показано один блок із зображенням і текстом.`,
  fJ = `Сіткою`,
  pJ = `Списком`,
  mJ = `Приховати розпродані пакунки`,
  hJ = `Якщо вибрано, пакунки, яких більше немає в наявності, видалятимуться з розділу, а не показуватимуться з кнопкою «Немає в наявності». Стандартно цю опцію вимкнено.`,
  gJ = `Кольори компактних рядків`,
  _J = `Це застосовується до опцій без опису, показаних в один рядок. Усе інше зі стандартним значенням виглядатиме звичайно.`,
  vJ = `Назва`,
  yJ = `Тло блоку`,
  bJ = `Ціна`,
  xJ = `Кнопка купівлі`,
  SJ = `Текст на кнопці купівлі`,
