  TJ = `Квадратна`,
  EJ = `Закруглена`,
  DJ = `Капсула`,
  OJ = `(Лише для Valve) Фасети`,
  kJ = `(Лише для Valve) Фасетний пошук`,
  AJ = `Дозволити користувачам фільтрувати й шукати продукти в цьому розділі. ЗВЕРНІТЬ УВАГУ! Якщо встановити цей прапорець, з нього буде вилучено всі вибрані продукти.`,
  jJ = `назвою`,
  MJ = `підзаголовком (необов’язково)`,
  NJ = `позначкою`,
  PJ = `Додати значення фасета`,
  FJ = `Додати фасет`,
  IJ = `Фасети: %1$s`,
  LJ = `Значення фасета: %1$s`,
  RJ = `Автоматично створювати фасети`,
  zJ = `Створити`,
  BJ = `Перезаписати наявні фасети?`,
  VJ = `Автоматичне створення фасетів перепише всі поточні фасети в цьому розділі. Продовжити?`,
  HJ = `Використовуйте функціональні мітки для застосунків із позначкою «Контролер» у крамниці.`,
  UJ = `Видалити невикористані фасети`,
  WJ = `Видалити`,
  GJ = `Мінімальна кількість капсул, що відповідають значенням фасета`,
  KJ = `Рекомендоване значення: 5`,
  qJ = `Максимальне значення для кожного фасета`,
  JJ = `Рекомендоване значення: 5`,
  YJ = `Сортувати значення фасетів`,
  XJ = `За назвою`,
  ZJ = `За кількістю збігів`,
  QJ = `Вручну`,
  $J = `Назва значення цього фасета. Значення фасета — це окремий параметр, який можна клацнути для фільтрування ігор, показаних у цьому розділі. Наприклад, «Від першої особи».`,
  eY = `Необов’язковий текст для показу праворуч від цього значення фасета. Використовується для надання дуже короткого пояснення значення фасета. Наприклад, «1–2 години» для ігор із коротким часом проходження.`,
  tY = `Назва цього фасета. Фасет — це група пов’язаних параметрів, кожен з яких можна клацнути для фільтрування ігор, показаних у цьому розділі. Наприклад, «Жанр».`,
  nY = `Автоматично заповнювати фасети та значення фасетів на основі категорій позначок у крамниці, наприклад «Жанр» і «Візуальний стиль і перспектива». Після автоматичного створення кожен фасет і значення фасета можна за потреби змінити вручну.`,
  rY = `Вилучати всі значення фасетів, які не відповідають жодному продукту в цьому розділі.`,
  iY = `Мінімальна кількість результатів, які ви бажаєте бачити для будь-якого вибраного фасета. У меню ліворуч будуть приховані всі терміни, які не мають принаймні такої кількості збігів. Ця кількість обчислюється після застосування фільтрів вкладки. Зазвичай прийнятна кількість — п’ять.`,
  aY = `Максимальна кількість опцій, які показуватимуться під будь-якою категорією найвищого рівня в меню ліворуч. Наприклад, під фасетом «Жанр» не показуватиметься більше ніж ця кількість жанрів. Зазвичай прийнятна кількість — п’ять.`,
  oY = `Сортувати значення для кожного фасета за цим показником. Зазвичай найкраще сортувати за кількістю збігів.`,
  sY = `Усередині кожного фасета: сортувати значення фасетів в алфавітному порядку їхніх назв.`,
  cY = `Усередині кожного фасета: сортувати значення фасетів за спаданням кількості відповідних їм продуктів. Наприклад, під фасетом «Жанр» «Рольова гра» з’явиться вище, ніж «Стратегія», якщо в цьому розділі рольових ігор більше, ніж стратегій.`,
